43		Name      string         `json:"name"`
44		Arguments map[string]any `json:"arguments"`
45	}
46	
47	func newMCPCommand(opts Options) *cobra.Command {
48		return &cobra.Command{
49			Use:   "mcp",
50			Short: "Serve local brain tools over MCP stdio",
51			Args:  cobra.NoArgs,
52			RunE: func(cmd *cobra.Command, args []string) error {
53				return runMCP(cmd.Context(), cmd.InOrStdin(), cmd.OutOrStdout(), opts)
54			},
55		}
56	}
57	
58	func runMCP(ctx context.Context, in io.Reader, out io.Writer, opts Options) error {
59		reader := bufio.NewReader(in)
60		debugLog := os.Getenv("ENTIRE_BRAIN_MCP_DEBUG_LOG")
61		mcpDebugLog(debugLog, "start")
62		for {
63			msg, frameMode, err := readMCPMessage(reader)
64			if errors.Is(err, io.EOF) {
65				mcpDebugLog(debugLog, "eof")
66				return nil
67			}
68			if errors.Is(err, errMCPRecoverable) {
69				// Reply with a JSON-RPC parse error and keep serving; one bad frame
70				// must not kill the whole MCP session.
71				mcpDebugLog(debugLog, "parse_error: "+err.Error())
72				resp := mcpMessage{JSONRPC: "2.0", Error: &mcpError{Code: -32700, Message: "parse error"}}
73				if werr := writeMCPMessage(out, resp, frameMode); werr != nil {
74					mcpDebugLog(debugLog, "write_error: "+werr.Error())
75					return werr
76				}
77				continue
78			}
79			if err != nil {
80				mcpDebugLog(debugLog, "read_error: "+err.Error())
81				return err
82			}
83			mcpDebugLog(debugLog, "message: "+msg.Method)
84			if msg.ID == nil {
85				continue
86			}
87			response := handleMCPMessage(ctx, opts, msg)
88			if err := writeMCPMessage(out, response, frameMode); err != nil {
89				mcpDebugLog(debugLog, "write_error: "+err.Error())
90				return err
91			}
92			mcpDebugLog(debugLog, "response: "+msg.Method)
93		}
94	}
95	
96	func mcpDebugLog(path, line string) {
97		if strings.TrimSpace(path) == "" {
98			return
99		}
100		f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
101		if err != nil {
102			return
103		}
104		defer f.Close()
105		fmt.Fprintln(f, line)
106	}
107	
108	func handleMCPMessage(ctx context.Context, opts Options, msg mcpMessage) mcpMessage {
109		response := mcpMessage{JSONRPC: "2.0", ID: msg.ID}
110		switch msg.Method {
111		case "initialize":
112			protocolVersion := mcpInitializeProtocolVersion(msg.Params)
113			response.Result = map[string]any{
114				"protocolVersion": protocolVersion,
115				"capabilities":    map[string]any{"tools": map[string]any{}},
116				"serverInfo":      map[string]any{"name": "entire-brain", "version": opts.Version},
117			}
118		case "tools/list":
119			response.Result = map[string]any{"tools": mcpToolDefinitions()}
120		case "tools/call":
121			result, err := handleMCPToolCall(ctx, opts, msg.Params)
122			if err != nil {
123				response.Error = &mcpError{Code: -32000, Message: err.Error()}
124			} else {
125				response.Result = result
126			}
127		default:
128			response.Error = &mcpError{Code: -32601, Message: "method not found"}
129		}
130		return response
131	}
132	
133	func mcpInitializeProtocolVersion(raw json.RawMessage) string {
134		const fallback = "2024-11-05"
135		var params struct {
136			ProtocolVersion string `json:"protocolVersion"`
137		}
138		if len(raw) == 0 || json.Unmarshal(raw, &params) != nil || strings.TrimSpace(params.ProtocolVersion) == "" {
139			return fallback
140		}
141		return params.ProtocolVersion
142	}
