1	package cli
2	
3	import (
4		"bufio"
5		"context"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14		"time"
15	
16		"github.com/spf13/cobra"
17	)
18	
19	// Regression Radar: turn the brain from a passive librarian into an active reviewer.
20	// Given a query (task description + failing identifiers) it compares the CURRENT working
21	// tree against what the session history asserts the code looked like, and flags two narrow,
22	// high-precision shapes of regression:
23	//
24	//	changed: history asserts `<id> + "<literal>"` (or a `..` range) at a locus, but the
25	//	         current tree keeps the distinctive operand while the identifier was swapped out
26	//	         (e.g. scopeBaseRef+"..HEAD"  ->  "master..HEAD").
27	//	deleted: history asserts an assignment whose target contains <id> (e.g.
28	//	         `state.TranscriptPath = resolved`) and that assignment is now absent EVERYWHERE in
29	//	         the candidate files, though the identifier still lives in the tree.
30	//
31	// It reads RAW sessions (inspectBrainRawText), not the index, because the indexed Summary
32	// collapses code to prose; the precise invariant survives only in raw text. Presence is checked
33	// GLOBALLY across the candidate files (an assignment that simply lives in a different file is not
34	// a regression) — a finding is emitted only when history asserts something the current code does
35	// not contain anywhere.
36	
37	const (
38		regressionMaxFileBytes = 1 << 20
39		regressionMaxAnomalies = 50
40	)
41	
42	type regressionAnomaly struct {
43		File       string  `json:"file"`
44		Line       int     `json:"line,omitempty"`
45		Kind       string  `json:"kind"` // "changed" | "deleted"
46		Current    string  `json:"current"`
47		Expected   string  `json:"expected"`
48		Identifier string  `json:"identifier"`
49		Confidence float64 `json:"confidence"`
50		Reason     string  `json:"reason"`
51		Evidence   string  `json:"evidence"`
52	}
53	
54	type regressionReport struct {
55		GeneratedAt time.Time           `json:"generated_at"`
56		Query       string              `json:"query"`
57		RepoPath    string              `json:"repo_path"`
58		BrainPath   string              `json:"brain_path"`
59		Anomalies   []regressionAnomaly `json:"anomalies"`
60		Scanned     int                 `json:"scanned_files"`
61		Warnings    []string            `json:"warnings,omitempty"`
62	}
63	
64	type regressionDetectorOptions struct {
65		limit            int
66		json             bool
67		includeDeletions bool // deletions are higher-recall but noisier (no recency data); opt-in
68	}
69	
70	type changeSignal struct {
71		id      string // lowercased identifier
72		operand string // distinctive operand, lowercased+despaced (e.g. `..head`)
73		raw     string // human-readable asserted expression
74		ev      string // session path:line
75	}
76	
77	type deleteSignal struct {
78		id     string
79		target string // normalized LHS + assignment op (e.g. `state.transcriptpath=`)
80		rhs    string // despaced right-hand side token (e.g. `resolved`) — used to locate the home file
81		raw    string
82		ev     string
83	}
84	
85	type candFile struct {
86		clean    string
87		lines    []string
88		norm     []string
89		semantic bool // surfaced by the semantic index (a primary locus), not just named in a session
90		rank     int  // semantic rank (lower = stronger locus)
91		isTest   bool
92	}
93	
94	func regressionIsComment(line string) bool {
95		t := strings.TrimSpace(line)
96		return strings.HasPrefix(t, "//") || strings.HasPrefix(t, "*") || strings.HasPrefix(t, "/*") ||
97			strings.HasPrefix(t, "#") || strings.HasPrefix(t, "<!--")
98	}
99	
100	func regressionIsTestPath(p string) bool {
101		l := strings.ToLower(p)
102		return strings.Contains(l, "_test.") || strings.Contains(l, ".test.") || strings.Contains(l, ".spec.") ||
103			strings.Contains(l, "/test/") || strings.Contains(l, "/tests/") || strings.Contains(l, "/testdata/")
104	}
105	
106	var regressionCodeFilePattern = regexp.MustCompile(`[\w./-]+\.(?:go|ts|tsx|js|jsx|py|rs|java|kt|swift|c|cc|cpp|h|hpp)`)
107	
108	func regressionDespace(s string) string {
109		var b strings.Builder
110		for _, r := range s {
111			if r == ' ' || r == '\t' {
112				continue
113			}
114			b.WriteRune(r)
115		}
116		return strings.ToLower(b.String())
117	}
118	
119	// regressionExtractSignals pulls change + delete signals for one identifier from a (space-
120	// collapsed) history excerpt using identifier-anchored regexes — tight enough that line-number
121	// noise and common tokens don't leak in.
122	func regressionExtractSignals(id, excerpt, ev string) ([]changeSignal, []deleteSignal) {
123		q := regexp.QuoteMeta(id)
124		changeRe := regexp.MustCompile(`(?i)` + q + `\s*\+?\s*(?:"([^"]{2,40})"|([A-Za-z0-9_]*\.\.[A-Za-z0-9_]+))`)
125		assignRe := regexp.MustCompile(`(?i)((?:[A-Za-z0-9_]+\.)*[A-Za-z0-9_]*` + q + `[A-Za-z0-9_]*)\s*(:?=)\s*([A-Za-z0-9_."'\[\]()+\-* ]{1,48})`)
126	
127		var changes []changeSignal
128		seenC := map[string]struct{}{}
129		for _, m := range changeRe.FindAllStringSubmatch(excerpt, -1) {
130			operand := m[1]
131			if operand == "" {
132				operand = m[2]
133			}
134			operand = regressionDespace(operand)
135			if len(operand) < 4 {
136				continue
137			}
138			if _, ok := seenC[operand]; ok {
139				continue
140			}
141			seenC[operand] = struct{}{}
142			changes = append(changes, changeSignal{id: id, operand: operand, raw: strings.TrimSpace(m[0]), ev: ev})
143		}
144	
145		var deletes []deleteSignal
146		seenD := map[string]struct{}{}
147		for _, m := range assignRe.FindAllStringSubmatch(excerpt, -1) {
148			lhs := regressionDespace(m[1])
149			op := m[2]
150			if !strings.Contains(lhs, id) {
151				continue
152			}
153			// Only field/state assignments (`a.b = c`) are persistent invariants whose absence is a
154			// regression; `:=` locals are ephemeral, so their absence from a file is meaningless.
155			if op != "=" || !strings.Contains(lhs, ".") {
156				continue
157			}
158			target := lhs + op
159			if _, ok := seenD[target]; ok {
160				continue
161			}
162			seenD[target] = struct{}{}
163			rhsTok := strings.TrimSpace(m[3])
164			if i := strings.IndexAny(rhsTok, " (.,"); i > 0 {
165				rhsTok = rhsTok[:i]
166			}
167			if rhsTok == "" {
168				continue
169			}
170			raw := strings.TrimSpace(m[1]) + " " + op + " " + rhsTok
171			deletes = append(deletes, deleteSignal{id: id, target: target, rhs: strings.ToLower(rhsTok), raw: raw, ev: ev})
172		}
173		return changes, deletes
174	}
175	
176	// regressionScanHistory walks the raw brain (sessions + exports) once and extracts change/delete
177	// signals for the given identifiers from EVERY matching line — not a capped top-N — so rare but
178	// precise invariants are not lost. Bounded by a generous file cap and a distinct-signal cap.
179	func regressionScanHistory(brainDir string, ids []string) ([]changeSignal, []deleteSignal, map[string]struct{}) {
180		const (
181			maxFiles       = 20000
182			maxLineBytes   = 4 * 1024 * 1024
183			maxSignalsEach = 400
184		)
185		lowIDs := make([]string, 0, len(ids))
186		for _, id := range ids {
187			lowIDs = append(lowIDs, strings.ToLower(id))
188		}
189		var changes []changeSignal
190		var deletes []deleteSignal
191		files := map[string]struct{}{}
192		seenC := map[string]struct{}{}
193		seenD := map[string]struct{}{}
194		scanned := 0
195		_ = filepath.WalkDir(brainDir, func(path string, d fs.DirEntry, err error) error {
196			if err != nil {
197				return nil
198			}
199			if d.IsDir() {
200				if n := d.Name(); n == semanticDirName || n == ".git" {
201					return filepath.SkipDir
202				}
203				return nil
204			}
205			if scanned >= maxFiles || (len(seenC) >= maxSignalsEach && len(seenD) >= maxSignalsEach) {
206				return filepath.SkipAll
207			}
208			switch filepath.Ext(path) {
209			case ".jsonl", ".json", ".md", ".txt":
210			default:
211				return nil
212			}
213			rel, _ := filepath.Rel(brainDir, path)
214			relSlash := filepath.ToSlash(rel)
215			if relSlash == "manifest.json" || strings.HasPrefix(relSlash, "seed/") {
216				return nil
217			}
218			f, openErr := os.Open(path)
219			if openErr != nil {
220				return nil
221			}
222			defer f.Close()
223			scanned++
224			sc := bufio.NewScanner(f)
225			sc.Buffer(make([]byte, 0, 64*1024), maxLineBytes)
226			lineNo := 0
227			for sc.Scan() {
228				lineNo++
229				line := sc.Text()
230				low := strings.ToLower(line)
231				matched := false
232				for _, id := range lowIDs {
233					if !strings.Contains(low, id) {
234						continue
235					}
236					matched = true
237					ex := normalizeHistoryTextForExcerpt(line)
238					ev := relSlash + ":" + strconv.Itoa(lineNo)
239					c, dl := regressionExtractSignals(id, ex, ev)
240					for _, s := range c {
241						if _, ok := seenC[s.id+"|"+s.operand]; !ok {
242							seenC[s.id+"|"+s.operand] = struct{}{}
243							changes = append(changes, s)
244						}
245					}
246					for _, s := range dl {
247						k := s.target + "|" + s.rhs
248						if _, ok := seenD[k]; !ok {
249							seenD[k] = struct{}{}
250							deletes = append(deletes, s)
251						}
252					}
253				}
254				if matched {
255					for _, fn := range regressionCodeFilePattern.FindAllString(line, -1) {
256						files[strings.TrimLeft(fn, "+-/ ")] = struct{}{}
257					}
258				}
259			}
260			return nil
261		})
262		return changes, deletes, files
263	}
264	
265	func detectRegressionAnomalies(brainDir, repoRoot string, semSource *semanticSourceManifest, query string, limit int, includeDeletions bool) ([]regressionAnomaly, int, []string) {
266		var warnings []string
267		ids := brainBriefRawHistoryQueries(query)
268		if len(ids) == 0 {
269			return nil, 0, []string{"no code identifiers found in query; pass the failing symbols/terms"}
270		}
271	
272		candidateFiles := map[string]struct{}{}
273		semanticRank := map[string]int{} // clean path -> best (lowest) semantic rank; lower = stronger locus
274		for _, rawID := range ids {
275			id := strings.ToLower(rawID)
276			if semSource != nil {
277				if syms, _, err := semanticContextFacts(brainDir, semSource, id, 8, 0); err == nil {
278					for rank, s := range syms {
279						if s.FilePath == "" {
280							continue
281						}
282						candidateFiles[s.FilePath] = struct{}{}
283						c := filepath.Clean(s.FilePath)
284						if r, ok := semanticRank[c]; !ok || rank < r {
285							semanticRank[c] = rank
286						}
287					}
288				}
289			}
290		}
291		// Targeted history scan: walk the raw sessions once, keeping only signal-bearing lines (so a
292		// rare invariant isn't lost behind thousands of plain identifier mentions, as a capped
293		// generic scan would). Also collects the code files those sessions name.
294		changes, deletes, namedFiles := regressionScanHistory(brainDir, ids)
295		for f := range namedFiles {
296			candidateFiles[f] = struct{}{}
297		}
298		if len(changes) == 0 && len(deletes) == 0 {
299			return nil, 0, append(warnings, "history holds no precise code assertions for these identifiers")
300		}
301	
302		// Load all candidate files once.
303		var files []candFile
304		for file := range candidateFiles {
305			clean := filepath.Clean(file)
306			if strings.HasPrefix(clean, "..") || filepath.IsAbs(clean) {
307				continue
308			}
309			full := filepath.Join(repoRoot, clean)
310			info, err := os.Stat(full)
311			if err != nil || info.IsDir() || info.Size() > regressionMaxFileBytes {
312				continue
313			}
314			data, err := os.ReadFile(full)
315			if err != nil {
316				continue
317			}
318			lines := strings.Split(string(data), "\n")
319			norm := make([]string, len(lines))
320			for i, ln := range lines {
321				norm[i] = regressionDespace(ln)
322			}
323			rank, isSem := semanticRank[clean]
324			if !isSem {
325				rank = 1 << 30
326			}
327			files = append(files, candFile{clean: clean, lines: lines, norm: norm, semantic: isSem, rank: rank, isTest: regressionIsTestPath(clean)})
328		}
329		if len(files) == 0 {
330			return nil, 0, append(warnings, "no current files to verify against (semantic index missing?)")
331		}
332		// Deterministic, locus-prioritized order: implementation before tests, then by semantic rank
333		// (the strongest fix-site first), then path — so a finding lands on the actual fix site, not a
334		// random file that happens to share a common operand like `..HEAD`.
335		sort.SliceStable(files, func(i, j int) bool {
336			if files[i].isTest != files[j].isTest {
337				return !files[i].isTest
338			}
339			if files[i].rank != files[j].rank {
340				return files[i].rank < files[j].rank
341			}
342			return files[i].clean < files[j].clean
343		})
344	
345		anyLineBoth := func(a, b string) bool {
346			for _, f := range files {
347				for _, n := range f.norm {
348					if strings.Contains(n, a) && strings.Contains(n, b) {
349						return true
350					}
351				}
352			}
353			return false
354		}
355		anyHas := func(needle string) bool {
356			for _, f := range files {
357				for _, n := range f.norm {
358					if strings.Contains(n, needle) {
359						return true
360					}
361				}
362			}
363			return false
364		}
365	
366		var anomalies []regressionAnomaly
367	
368		for _, c := range dedupeChanges(changes) {
369			if anyLineBoth(c.operand, c.id) {
370				continue // invariant still holds somewhere
371			}
372			for _, f := range files { // locate the swap: operand present, identifier gone
373				if f.isTest {
374					continue // a test's `..HEAD` is not the regressed implementation site
375				}
376				found := false
377				for i, n := range f.norm {
378					if regressionIsComment(f.lines[i]) {
379						continue // prose mentions of a range like `main...HEAD` are not the regression
380					}
381					if strings.Contains(n, c.operand) && !strings.Contains(n, c.id) {
382						anomalies = append(anomalies, regressionAnomaly{
383							File: f.clean, Line: i + 1, Kind: "changed",
384							Current: strings.TrimSpace(f.lines[i]), Expected: c.raw,
385							Identifier: c.id, Confidence: 0.85, Evidence: c.ev,
386							Reason: fmt.Sprintf("history asserts %q; this line keeps %q but dropped %q", c.raw, c.operand, c.id),
387						})
388						found = true
389						break
390					}
391				}
392				if found {
393					break
394				}
395			}
396		}
397	
398		for _, d := range dedupeDeletes(deletes) {
399			if !includeDeletions {
400				break // deletions are higher-recall but noisier (benign churn) — opt-in only
401			}
402			// The SPECIFIC assignment (target + its RHS) must be absent everywhere — a different
403			// assignment to the same field in another file is not this regression.
404			if anyHas(d.target+d.rhs) || !anyHas(d.id) {
405				continue
406			}
407			// Locate the home file: prefer one that also holds the RHS token (the natural site of
408			// the assignment), else the first file where the identifier appears.
409			home, line, cur := regressionHomeFile(files, d.id, d.rhs)
410			if home == "" {
411				continue
412			}
413			anomalies = append(anomalies, regressionAnomaly{
414				File: home, Line: line, Kind: "deleted",
415				Current: cur, Expected: d.raw,
416				Identifier: d.id, Confidence: 0.65, Evidence: d.ev,
417				Reason: fmt.Sprintf("history asserts `%s` but that assignment is absent everywhere in the current tree", d.raw),
418			})
419		}
420	
421		anomalies = regressionDedupeRank(anomalies)
422		if limit > 0 && len(anomalies) > limit {
423			anomalies = anomalies[:limit]
424		}
425		if len(anomalies) > regressionMaxAnomalies {
426			anomalies = anomalies[:regressionMaxAnomalies]
427		}
428		return anomalies, len(files), warnings
429	}
430	
431	// regressionHomeFile returns the best (file, line, text) to attribute a deletion to: a file
432	// containing both the identifier and the RHS token, else the first file holding the identifier.
433	func regressionHomeFile(files []candFile, id, rhs string) (string, int, string) {
434		if rhs != "" {
435			for _, f := range files {
436				if !fileHasNorm(f.norm, rhs) {
437					continue
438				}
439				for i, n := range f.norm {
440					if strings.Contains(n, id) {
441						return f.clean, i + 1, strings.TrimSpace(f.lines[i])
442					}
443				}
444			}
445		}
446		for _, f := range files {
447			for i, n := range f.norm {
448				if strings.Contains(n, id) {
449					return f.clean, i + 1, strings.TrimSpace(f.lines[i])
450				}
451			}
452		}
453		return "", 0, "(absent)"
454	}
455	
456	func fileHasNorm(norm []string, needle string) bool {
457		for _, n := range norm {
458			if strings.Contains(n, needle) {
459				return true
460			}
461		}
462		return false
463	}
464	
465	func dedupeChanges(in []changeSignal) []changeSignal {
466		seen := map[string]struct{}{}
467		var out []changeSignal
468		for _, c := range in {
469			k := c.id + "|" + c.operand
470			if _, ok := seen[k]; ok {
471				continue
472			}
473			seen[k] = struct{}{}
474			out = append(out, c)
475		}
476		return out
477	}
478	
479	func dedupeDeletes(in []deleteSignal) []deleteSignal {
480		seen := map[string]struct{}{}
481		var out []deleteSignal
482		for _, d := range in {
483			k := d.target + "|" + d.rhs
484			if _, ok := seen[k]; ok {
485				continue
486			}
487			seen[k] = struct{}{}
488			out = append(out, d)
489		}
490		return out
491	}
492	
493	func regressionDedupeRank(in []regressionAnomaly) []regressionAnomaly {
494		seen := map[string]struct{}{}
495		var out []regressionAnomaly
496		for _, a := range in {
497			key := a.File + "|" + a.Kind + "|" + regressionDespace(a.Expected)
498			if _, ok := seen[key]; ok {
499				continue
500			}
501			seen[key] = struct{}{}
502			out = append(out, a)
503		}
504		sort.SliceStable(out, func(i, j int) bool {
505			if out[i].Confidence != out[j].Confidence {
506				return out[i].Confidence > out[j].Confidence
507			}
508			return out[i].File < out[j].File
509		})
510		return out
511	}
512	
513	func runRegressionDetect(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
514		if ro.limit <= 0 {
515			ro.limit = 20
516		}
517		target := agentSurfaceTarget(opts, nil)
518		status, err := buildBrainStatusReport(ctx, opts, target)
519		if err != nil {
520			return err
521		}
522		var semSource *semanticSourceManifest
523		if status.Manifest != nil && status.Manifest.Sources != nil {
524			semSource = status.Manifest.Sources.Semantic
525		}
526		anomalies, scanned, warnings := detectRegressionAnomalies(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit, ro.includeDeletions)
527		report := regressionReport{
528			GeneratedAt: opts.Now().UTC(),
529			Query:       query,
530			RepoPath:    status.Repo.Root,
531			BrainPath:   status.Brain.Path,
532			Anomalies:   anomalies,
533			Scanned:     scanned,
534			Warnings:    warnings,
535		}
536		if ro.json {
537			return writeJSON(cmd, report)
538		}
539		out := cmd.OutOrStdout()
540		if len(anomalies) == 0 {
541			fmt.Fprintf(out, "No suspected regressions for %q (scanned %d files).\n", query, scanned)
542			for _, w := range warnings {
543				fmt.Fprintf(out, "  note: %s\n", w)
544			}
545			return nil
546		}
547		fmt.Fprintf(out, "Suspected regressions for %q:\n", query)
548		for _, a := range anomalies {
549			fmt.Fprintf(out, "  [%s, conf %.2f] %s:%d\n    expected: %s\n    current:  %s\n    why: %s\n    evidence: %s\n",
550				a.Kind, a.Confidence, a.File, a.Line, a.Expected, a.Current, a.Reason, a.Evidence)
551		}
552		return nil
553	}
554	
555	func newInspectRegressionsCommand(opts Options) *cobra.Command {
556		ro := regressionDetectorOptions{limit: 20}
557		cmd := &cobra.Command{
558			Use:   "regressions <query>",
559			Short: "Flag suspected regressions by comparing current code to session history",
560			Args:  cobra.ExactArgs(1),
561			RunE: func(cmd *cobra.Command, args []string) error {
562				return runRegressionDetect(cmd.Context(), cmd, opts, ro, args[0])
563			},
564		}
565		cmd.Flags().IntVar(&ro.limit, "limit", 20, "Maximum suspected regressions to return")
566		cmd.Flags().BoolVar(&ro.json, "json", false, "Emit machine-readable JSON")
567		cmd.Flags().BoolVar(&ro.includeDeletions, "include-deletions", false, "Also flag deleted assignments (higher recall, noisier)")
568		return cmd
569	}
