export const meta = {
  name: 'regression-radar-audit',
  description: 'Full multi-dimension audit of the Regression Radar feature (regression.go + MCP tool + eval harness) on branch claude/regression-radar',
  phases: [
    { title: 'Review' },
    { title: 'Synthesize' },
  ],
}

const REPO = '/Users/suhaan/Documents/Coding/entire-brain'

const FINDINGS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    dimension: { type: 'string' },
    summary: { type: 'string', description: 'one-paragraph verdict for this dimension' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low', 'info'] },
          location: { type: 'string', description: 'file:line' },
          title: { type: 'string' },
          detail: { type: 'string', description: 'what is wrong, why it matters' },
          suggestion: { type: 'string' },
        },
        required: ['severity', 'title', 'detail'],
      },
    },
  },
  required: ['dimension', 'summary', 'findings'],
}

const COMMON = `Repo root: ${REPO}. Branch: claude/regression-radar (3 commits, ~786 lines). The feature is "Regression Radar": given a query (task + failing identifiers) it compares the CURRENT working tree against what session history asserts the code looked like, and flags two narrow shapes:
- "changed": history asserts \`<id>+"<literal>"\` or an \`<id>..<id>\` range; flag a line where the distinctive operand survives but the identifier was swapped out (e.g. scopeBaseRef+"..HEAD" -> "master..HEAD").
- "deleted" (opt-in --include-deletions): history asserts a field assignment \`a.b.<id> = rhs\`; flag if that exact assignment is absent EVERYWHERE in candidate files.
Core files: internal/cli/regression.go (engine, ~570 lines), internal/cli/regression_test.go, internal/cli/mcp.go (brain_regressions tool ~line 187-191 and dispatch ~258), internal/cli/agent_surface.go (brainBriefRawHistoryQueries identifier extractor), internal/cli/history.go (normalizeHistoryTextForExcerpt, inspectBrainRawText), benchmarks/agent-brain/regression_eval.py, benchmarks/agent-brain/run.py (env-gated delivery, +14). Read the actual code (use git show / Read / Grep). Report ONLY real, evidence-backed findings with file:line. Do not fix anything.`

const dims = [
  {
    key: 'algorithm-correctness',
    prompt: `${COMMON}

DIMENSION: Algorithm correctness of internal/cli/regression.go. Read it in FULL plus its helpers in agent_surface.go (brainBriefRawHistoryQueries) and history.go (normalizeHistoryTextForExcerpt). Scrutinize:
- regressionExtractSignals regexes (line ~122): are the change/delete regexes correct? Can they mis-capture, over-match, or miss real invariants? Edge cases: operand with embedded quotes, ranges like a..b where a or b empty, the {2,40}/{1,48} length caps, case-insensitive matching against a despaced excerpt.
- The "changed" detection (line ~368): anyLineBoth global-presence guard, comment-skip, test-skip, the operand>=4 floor, the dedupe. Can it emit a wrong line? Can it miss the true site?
- The "deleted" detection (line ~398): the anyHas(target+rhs) / !anyHas(id) logic, op=='=' && contains('.') filter, regressionHomeFile attribution. Soundness of "absent everywhere == regression".
- Determinism: WalkDir order, map iteration over candidateFiles/namedFiles, the sort.SliceStable tie-breaks — is output stable across runs?
- Robustness: nil semSource, empty ids, files with \\r\\n, multi-byte UTF-8 in despace/excerpt, huge lines (maxLineBytes), the regressionMaxFileBytes / maxFiles / maxSignalsEach caps — any panic, index-out-of-range, or silent truncation that drops real signals.
Return structured findings.`,
  },
  {
    key: 'adversarial-false-positives',
    prompt: `${COMMON}

DIMENSION: Adversarially BREAK the detector. The headline claim (project memory) is "precise changed-detection, 0 false alarms; deletions noisy/opt-in." Try hard to falsify it. Construct concrete scenarios (describe exact session-history text + current-tree code) that would make the detector:
(a) FALSE POSITIVE — flag a regression where none exists. E.g. an operand like "..head" or a 4-char literal that legitimately appears with a different identifier in unrelated code; a refactor that renamed an identifier intentionally; the same range used in two features; operand collisions across files.
(b) FALSE NEGATIVE — miss a real regression. E.g. invariant expressed in a way the regex doesn't anchor; the operand also surviving in a comment/test so anyLineBoth passes; identifier casing; multi-line assertions collapsed by normalize.
For each scenario state: the history text, the current code, what the detector does, and whether that's wrong. Judge whether "0 false alarms" is defensible or marketing. Be concrete — cite the exact code path (line) that produces the wrong behavior. Return structured findings (severity reflects likelihood × impact in real repos).`,
  },
  {
    key: 'security-resources',
    prompt: `${COMMON}

DIMENSION: Security + resource safety. Examine:
- PATH TRAVERSAL: candidate files come from (1) the semantic index and (2) regressionCodeFilePattern matches scraped from raw session lines (line ~255, strings.TrimLeft(fn, "+-/ ")). Those file paths are then filepath.Join(repoRoot, clean) and os.ReadFile'd (line ~304-317). The guard is \`strings.HasPrefix(clean, "..") || filepath.IsAbs(clean)\` after filepath.Clean. Is that guard sufficient? Can a crafted session (e.g. checkpoint trailer / transcript containing a path like \`../../etc/passwd\` or \`foo/../../../etc/passwd\` or an absolute path) cause a read outside repoRoot? Test the logic precisely (filepath.Clean then HasPrefix ".." — does it catch \`a/../../x\`?).
- ReDoS: regressionExtractSignals builds regexes from regexp.QuoteMeta(id) where id comes from the user query. Go's RE2 has no catastrophic backtracking, but confirm; also confirm a pathological id can't blow up.
- RESOURCE BOUNDS: maxFiles=20000, maxLineBytes=4MiB, maxSignalsEach=400, regressionMaxFileBytes=1MiB, the WalkDir over the whole brain dir. Memory/time on a huge brain? Any unbounded slice growth?
- MCP tool (mcp.go brain_regressions ~258): input validation of query/limit; does it leak anything; does it run the same bounded path.
- Does it ever WRITE anything or only read? Confirm read-only (matches the no-egress / local-only product claim).
Return structured findings; clearly separate real vulnerabilities from acceptable-for-local-tool risk.`,
  },
  {
    key: 'eval-integrity',
    prompt: `${COMMON}

DIMENSION: Integrity of the A/B eval that will be used to justify this feature. Read benchmarks/agent-brain/regression_eval.py IN FULL and the run.py diff (git diff origin/main...HEAD -- benchmarks/agent-brain/run.py). A skeptical CEO will attack the eval. Check:
- What exactly does regression_eval.py measure? Does it honestly compare brain-with-regression-radar vs without? Or does it just run the detector on known-planted regressions (which proves recall on a fitted set, not real-world value)?
- Is the "0 false alarms" / precision claim measured on a held-out / realistic set, or on the same 1-2 tasks the detector was tuned on (overfitting)? Is there any negative/control set (clean trees that should yield ZERO findings) to measure false-positive rate?
- run.py env-gated delivery: how is brain_regressions delivered to the agent in the A/B? Does enabling it leak the answer (the planted regression's file/line) to the agent via the tool output, making the comparison circular?
- Sample size, determinism, and whether the eval could be presented as stronger than it is.
Return structured findings + the single sharpest question a hostile reviewer would ask.`,
  },
  {
    key: 'tests-and-wiring',
    prompt: `${COMMON}

DIMENSION: Test quality + integration wiring. Read internal/cli/regression_test.go IN FULL, the mcp.go brain_regressions wiring (definition ~187 and dispatch ~258), and the agent_surface.go one-line change (git show). Check:
- Do the tests assert REAL behavior (a planted changed/deleted regression is found at the right file:line with right confidence; a clean tree yields ZERO findings; comments/tests are skipped; the global-presence guard works) or are they shallow/tautological? Is there a NEGATIVE test (no false positive on a clean tree)? Coverage gaps for the adversarial cases.
- mcp.go: is brain_regressions dispatched correctly, with the same bounds as the CLI? Does it parse query/limit right? Any inconsistency between the MCP tool description and what the code does.
- Does \`go test ./internal/cli/ -run Regress\` actually exercise the engine end-to-end? Run it. Report pass/skip counts.
- The inspect-regressions command wiring (newInspectRegressionsCommand) — is it registered under inspect, flags correct.
Return structured findings.`,
  },
]

phase('Review')
const reviews = await parallel(
  dims.map((d) => () => agent(d.prompt, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA }))
)
const valid = reviews.filter(Boolean)

phase('Synthesize')
const packed = valid.map((r) => `### ${r.dimension}\nVERDICT: ${r.summary}\n` +
  (r.findings || []).map((f) => `- [${f.severity}] ${f.location || ''} ${f.title}: ${f.detail}${f.suggestion ? ' | FIX: ' + f.suggestion : ''}`).join('\n')
).join('\n\n')

const synthesis = await agent(
  `You are the lead reviewer writing the FINAL audit of the Regression Radar feature for a CEO. Below are structured findings from 5 parallel review dimensions. Synthesize into one report:
1. One-line VERDICT (ship / ship-with-fixes / not-ready) with the headline risk.
2. A severity-ranked list of the REAL issues (merge duplicates across dimensions, drop noise). Each: severity, file:line, one-line title, one-line why.
3. An honest take on the "0 false alarms / precise" claim — is it defensible, and under what conditions does it break?
4. Eval-integrity verdict: can this feature's benefit be honestly demonstrated as-is, or does the eval need a control/false-positive set first?
5. Top 3 things to fix before this is CEO-presentable.
Be concise and brutally honest; do not invent issues not in the findings. Findings:\n\n${packed}`,
  { label: 'synthesis', phase: 'Synthesize' }
)

return { synthesis, dimensions: valid.map((r) => ({ dimension: r.dimension, summary: r.summary, count: (r.findings || []).length })) }

