139	// watchTick runs one pass: cheap change detection, then (only on change) the free deterministic refresh
140	// and the gated distill. agentCalls is shared across ticks/members so --budget caps total token spend.
141	func watchTick(ctx context.Context, out io.Writer, w watchCommandOptions, cursorPath string, steps watchSteps, agentCalls *int) {
142		cursor := loadWatchCursor(cursorPath)
143		fp := steps.fingerprint(ctx)
144		changed := fp != cursor.LastFingerprint || cursor.LastRefreshAt.IsZero()
145		if !changed {
146			fmt.Fprintln(out, "[watch] no change; nothing to do")
147			return
148		}
149		if err := steps.refresh(ctx); err != nil {
150			fmt.Fprintf(out, "[watch] refresh failed: %v\n", err)
151		} else {
152			cursor.LastFingerprint = fp
153			cursor.LastRefreshAt = steps.now().UTC()
154			_ = saveWatchCursor(cursorPath, cursor)
155			fmt.Fprintln(out, "[watch] refreshed (deterministic, no agent tokens)")
156		}
157		if ok, reason := watchShouldDistill(w, cursor, *agentCalls, steps.now().UTC()); w.distill && !ok {
158			fmt.Fprintf(out, "[watch] distill skipped: %s\n", reason)
159		} else if ok {
160			if err := steps.distill(ctx); err != nil {
161				fmt.Fprintf(out, "[watch] distill failed: %v\n", err)
162			} else {
163				cursor.LastDistillAt = steps.now().UTC()
